            if (error) {
              console.log('*** error   i=' + i + '   j=' + j + '   msg=' + error.message +
                 '   want this');
              return reject(error);
            }
            console.log('in cp   cp('+ i + ', ' + j +
                    ')     result=' + result + '   want this');
            return resolve(result);
          })
          .catch(function(err) {
            console.log(err, "caught"); // test6
          });
      } // if (i &lt; reps)
      console.log('in cp   resolving   i=' + i +
              '   j=' + j + '      want this');
      return resolve('done');
    } // ender
    ender();
